catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    g_form.hideFieldMsg('telework_start_date', true);
    g_form.hideFieldMsg('telework_end_date', true);

    var msg = "";

    //debugger;

    // Check Start Date is in current year or next year but not later
    // If Start Date ok, check that End Date is in same year.  Update End Date to Dec 31 of same year as Start Date.
    var startDate = g_form.getValue('telework_start_date');
    var endDate = g_form.getValue("telework_end_date");

    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMTelWrkUtils');
    ga.addParam('sysparm_name', 'checkDateYear');
    ga.addParam('sysparm_date_to_check', startDate);
    ga.addParam('sysparm_other_date', endDate);
    ga.addParam('sysparm_is_start', "true");
    ga.getXMLAnswer(resultDateYear);

    // GlideAjax callback function
    function resultDateYear(answer) {
        var resultsObj = JSON.parse(answer);

        if (resultsObj.goodYear == "false") {
            msg = getMessage('x_hccc_hoc_ohs.telework_start_date_year_bad');
            g_form.showFieldMsg('telework_start_date', msg, 'error');
        } else if (resultsObj.endDate != "") {
            g_form.setValue('telework_end_date', resultsObj.endDate);
        }
        // If End Date is empty, skip comparing dates
        endDate = g_form.getValue("telework_end_date");
        if (endDate != "") {

            // Get date format used
            var format = g_user_date_format;

            // If new value for From date is after To date, show error message
            // 1 (true) if start is greater than end
            // 0 if end is greater than start of if they are the same
            // -1 if either of the dates is in an invalid format
            var isStartAfterEnd = compareDates(newValue, format, endDate, format);
            if (isStartAfterEnd) {
                msg = getMessage('x_hccc_hoc_ohs.start_date_before_end_date');
                g_form.showFieldMsg('telework_start_date', msg, 'error');
                //return;
            }
        }

    }
}
